import {careerFamilies,pathCareerIds,isTraining} from './guide-state.js?v=0.31.0';
import {occupations,occupationById} from './occupation-data.js?v=0.31.0';
import {directions} from './content.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {groupedOccupations} from './catalog-grouping-data.js?v=0.31.0';
const count=(n,label)=>`${n} ${label}${n===1?'':'s'}`;
export function careerTree(query=''){
 const q=query.trim().toLowerCase();return careerFamilies.map(f=>({...f,branches:f.paths.map(id=>{const d=directions.find(x=>x.id===id),familyMatch=[f.title,d?.title].some(t=>t?.toLowerCase().startsWith(q));return {id,title:d?.title||id,careers:pathCareerIds(id).map(occupationById).filter(Boolean).filter(o=>!q||familyMatch||[o.title,...o.aliases,...(o.searchTerms||[])].some(t=>t.toLowerCase().includes(q))),grouped:groupedOccupations.filter(o=>o.path===id&&(!q||familyMatch||o.title.toLowerCase().includes(q))).sort((a,b)=>(b.nationalEmployment||0)-(a.nationalEmployment||0))};}).filter(b=>b.careers.length||b.grouped.length)})).filter(f=>f.branches.length);
}
export function careerTreePage(query=''){
 const tree=careerTree(query),shown=new Set(tree.flatMap(f=>f.branches.flatMap(b=>b.careers.map(c=>c.id)))),grouped=new Set(tree.flatMap(f=>f.branches.flatMap(b=>b.grouped.map(c=>c.soc))));return `<p><a class="text-link" href="#/degree-careers">Explore 404 college & graduate careers →</a></p><a class="text-link" href="#/guide/paths">← Back to my guide</a><div class="page-intro guide-intro"><span class="eyebrow">THE CAREER TREE</span><h1>Start broad. Find your kind of work.</h1><p>${occupations.length} guided profiles. ${groupedOccupations.length} more roles grouped into related fields.</p><a class="tree-entry-link" href="#/catalog-coverage">How we chose the 50 additions →</a></div><label class="tree-search-label" for="career-tree-search">Find a career or interest</label><input id="career-tree-search" type="search" value="${h(query)}" placeholder="Try doctor, dentist, music, or engineering" autocomplete="off"><p class="tree-result-count" role="status">${count(shown.size,'profile')} · ${count(grouped.size,'grouped title')}${query?' · Matching branches are open.':''}</p><div class="career-tree">${tree.map(f=>`<details class="tree-family" ${query?'open':''}><summary><span aria-hidden="true">${f.symbol}</span><strong>${h(f.title)}</strong><span>${count(new Set(f.branches.flatMap(b=>b.careers.map(c=>c.id))).size,'profile')}</span></summary><div class="tree-branches">${f.branches.map(b=>`<section class="tree-branch"><h2>${h(b.title)}</h2><div>${b.careers.map(c=>`<a class="tree-career" data-action="tree-career" data-id="${c.id}" href="#/career/${c.id}"><strong>${h(c.title)}</strong><span>${isTraining(c)?'Practical training':c.finance?.credentialLevel==='graduate'||c.preparation.typicalEducation.some(x=>/doctoral|doctor|PhD/i.test(x))?'College + further study':'College route'}</span><b aria-hidden="true">→</b></a>`).join('')}</div>${b.grouped.length?`<details class="grouped-titles" ${query?'open':''}><summary>${count(b.grouped.length,'related title')}</summary><p>These belong in this field. Requirements and pay may differ from the profiles above.</p><button class="button secondary" data-action="tree-field" data-id="${b.id}">Explore this field →</button><ul>${b.grouped.map(c=>`<li><strong>${h(c.title)}</strong><a href="${h(c.sourceURL)}" target="_blank" rel="noopener noreferrer" aria-label="Official profile: ${h(c.title)}">Official details ↗</a></li>`).join('')}</ul></details>`:''}</section>`).join('')}</div></details>`).join('')||'<section class="guide-input-panel"><h2>Try another name for the work.</h2><p>Search a broader field or clear the search.</p><button class="button" data-action="clear-tree-search">Show the whole tree →</button></section>'}</div><details class="more-info"><summary>What this tree includes</summary><p>The 50 additions balance common jobs, missing fields, and distinct preparation routes. This is not a ranking of career value. Some very common jobs still sit in a grouped field. Grouped titles have official descriptions; they do not yet have a separate Fieldguide financial plan.</p><p>Physician represents family medicine; dentist represents general dentistry. Specialty pay and requirements differ.</p><a href="#/catalog-coverage">Coverage and research →</a></details>`;
}
